CREATE TABLE IF NOT EXISTS george_martin ( author STRING, PRIMARY KEY (author) NOT ENFORCED ) DISTRIBUTED BY HASH(author) INTO 1 BUCKETS WITH ( 'value.format' = 'avro-registry', 'scan.startup.mode' = 'earliest-offset', 'value.fields-include' = 'all', 'kafka.retention.time' = '0', 'kafka.producer.compression.type' = 'snappy', 'scan.bounded.mode' = 'unbounded' );